// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 callerBalance, uint256 blockNum) public {
        vm.assume(callerBalance >= 10 ether);
        address caller = address(0xb0b);
        vm.deal(caller, callerBalance);
        vm.deal(address(c), 0);
        vm.warp(1);
        vm.roll(blockNum);
        if (blockNum % 15 == 0) {
            uint256 preCallerBal = caller.balance;
            uint256 contractBalBefore = address(c).balance;
            vm.prank(caller);
            (bool ok,) = address(c).call{value: 10 ether}("");
            assertTrue(ok);
            assertTrue(caller.balance == preCallerBal + contractBalBefore);
        } else {
            vm.prank(caller);
            (bool ok,) = address(c).call{value: 10 ether}("");
            assertTrue(ok);
        }
    }
}
